// swift-tools-version: 6.0
import PackageDescription

let package = Package(
    name: "ReleaseLens",
    platforms: [.macOS(.v14)],
    products: [
        .library(name: "ReleaseLensCore", targets: ["ReleaseLensCore"]),
        .executable(name: "releaselens", targets: ["releaselens"]),
    ],
    targets: [
        .target(name: "ReleaseLensCore"),
        .executableTarget(name: "releaselens", dependencies: ["ReleaseLensCore"]),
    ]
)

import Foundation
import ReleaseLensCore

let arguments = Array(CommandLine.arguments.dropFirst())
guard arguments.count == 2 || arguments.count == 3,
      arguments.first == "scan",
      arguments.count == 2 || arguments[2] == "--pretty" else {
    FileHandle.standardError.write(Data("Usage: releaselens scan <artifact-path> [--pretty]\n".utf8))
    exit(64)
}

do {
    let summary = try ArtifactScanner().scan(URL(fileURLWithPath: arguments[1]))
    let encoder = JSONEncoder()
    encoder.outputFormatting = arguments.count == 3 ? [.prettyPrinted, .sortedKeys] : [.sortedKeys]
    FileHandle.standardOutput.write(try encoder.encode(summary))
    FileHandle.standardOutput.write(Data("\n".utf8))
} catch {
    FileHandle.standardError.write(Data("\(error.localizedDescription)\n".utf8))
    exit(1)
}

