import Foundation

public enum ArtifactKind: String, Codable, Sendable {
    case application, framework, bundle, package, diskImage, directory, file
}

/// Space contributed by a single top-level entry of an artifact.
public struct SpaceContribution: Codable, Equatable, Sendable {
    /// Name of the top-level child, or `other` for the aggregate of loose,
    /// non-directory occupancy (the artifact itself and root-level files).
    public let name: String
    public let regularFileCount: Int
    public let totalBytes: UInt64

    public init(name: String, regularFileCount: Int, totalBytes: UInt64) {
        self.name = name
        self.regularFileCount = regularFileCount
        self.totalBytes = totalBytes
    }

    /// Reserved name of the aggregate bucket; never a real bucket key.
    public static let otherName = "other"
}

/// The top-level subdirectory contributing the most bytes.
public struct LargestContributor: Codable, Equatable, Sendable {
    public let name: String
    public let totalBytes: UInt64
    /// True when one or more other top-level subdirectories contribute the
    /// exact same byte count. The winner is then the lexicographically smallest
    /// name among the tied contributors, independently of enumeration order.
    public let tied: Bool

    public init(name: String, totalBytes: UInt64, tied: Bool) {
        self.name = name
        self.totalBytes = totalBytes
        self.tied = tied
    }
}

public struct ArtifactSummary: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64
    /// Per-top-level-entry byte and regular-file breakdown. Named subdirectories
    /// are ordered by name; the trailing `other` entry collects everything not
    /// attributable to a top-level subdirectory. The entries' `totalBytes`
    /// always sum to `totalBytes`.
    public let breakdown: [SpaceContribution]
    /// The top-level subdirectory with the largest byte contribution, or nil
    /// when there are no subdirectories or every subdirectory contributes zero.
    public let largestContributor: LargestContributor?

    public init(path: String, name: String, kind: ArtifactKind, regularFileCount: Int,
                symbolicLinkCount: Int, totalBytes: UInt64,
                breakdown: [SpaceContribution], largestContributor: LargestContributor?) {
        self.path = path
        self.name = name
        self.kind = kind
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
        self.breakdown = breakdown
        self.largestContributor = largestContributor
    }
}

public enum ArtifactScannerError: Error, LocalizedError, Equatable {
    case missing(String)
    case unreadable(String)

    public var errorDescription: String? {
        switch self {
        case .missing(let path): "Artifact does not exist: \(path)"
        case .unreadable(let path): "Artifact cannot be inspected: \(path)"
        }
    }
}

public struct ArtifactScanner: Sendable {
    public init() {}

    /// Bucket key: a named top-level subdirectory, or the `other` aggregate.
    private enum BucketKey: Hashable {
        case named(String)
        case other
    }

    private struct Bucket {
        var regularFileCount = 0
        var totalBytes: UInt64 = 0
    }

    public func scan(_ input: URL) throws -> ArtifactSummary {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }

        let keys: Set<URLResourceKey> = [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey]
        guard let rootValues = try? url.resourceValues(forKeys: keys) else { throw ArtifactScannerError.unreadable(url.path) }

        var regularFiles = rootValues.isRegularFile == true ? 1 : 0
        var symbolicLinks = rootValues.isSymbolicLink == true ? 1 : 0
        let rootBytes = UInt64(max(rootValues.fileSize ?? 0, 0))

        // The root itself (a plain file, or the directory's own catalog entry)
        // belongs to no top-level subdirectory and therefore starts `other`.
        var buckets: [BucketKey: Bucket] = [.other: Bucket(regularFileCount: regularFiles, totalBytes: rootBytes)]
        var traversalError: ArtifactScannerError?

        if rootValues.isDirectory == true {
            guard let enumerator = manager.enumerator(
                at: url,
                includingPropertiesForKeys: Array(keys),
                options: [.skipsHiddenFiles, .skipsPackageDescendants],
                errorHandler: { failedURL, _ in
                    // Any unreadable descendant makes the whole scan untrustworthy.
                    traversalError = .unreadable(failedURL.path)
                    return false
                }
            ) else {
                throw ArtifactScannerError.unreadable(url.path)
            }

            let rootComponentCount = url.pathComponents.count

            while let child = enumerator.nextObject() as? URL {
                let values: URLResourceValues
                do {
                    values = try child.resourceValues(forKeys: keys)
                } catch {
                    throw ArtifactScannerError.unreadable(child.path)
                }

                if values.isSymbolicLink == true { symbolicLinks += 1; continue }
                guard values.isRegularFile == true else { continue }

                let size = UInt64(max(values.fileSize ?? 0, 0))
                regularFiles += 1

                // A depth-1 descendant is a direct child of the root; a regular
                // file there is loose occupancy and goes to `other`.
                let key: BucketKey
                if child.pathComponents.count == rootComponentCount + 1 {
                    key = .other
                } else {
                    key = .named(child.pathComponents[rootComponentCount])
                }
                var bucket = buckets[key] ?? Bucket()
                bucket.regularFileCount += 1
                bucket.totalBytes += size
                buckets[key] = bucket
            }
        }

        if let traversalError { throw traversalError }

        let totalBytes = buckets.values.reduce(UInt64(0)) { $0 + $1.totalBytes }
        let breakdown = makeBreakdown(from: buckets)
        let largestContributor = makeLargestContributor(from: buckets)

        return ArtifactSummary(
            path: url.path,
            name: url.lastPathComponent,
            kind: kind(for: url, isDirectory: rootValues.isDirectory == true),
            regularFileCount: regularFiles,
            symbolicLinkCount: symbolicLinks,
            totalBytes: totalBytes,
            breakdown: breakdown,
            largestContributor: largestContributor
        )
    }

    private func makeBreakdown(from buckets: [BucketKey: Bucket]) -> [SpaceContribution] {
        let named = buckets
            .compactMap { key, bucket -> SpaceContribution? in
                guard case .named(let name) = key else { return nil }
                return SpaceContribution(name: name, regularFileCount: bucket.regularFileCount, totalBytes: bucket.totalBytes)
            }
            .sorted { $0.name < $1.name }

        let other = buckets[.other].map {
            SpaceContribution(name: SpaceContribution.otherName, regularFileCount: $0.regularFileCount, totalBytes: $0.totalBytes)
        } ?? SpaceContribution(name: SpaceContribution.otherName, regularFileCount: 0, totalBytes: 0)

        return named + [other]
    }

    private func makeLargestContributor(from buckets: [BucketKey: Bucket]) -> LargestContributor? {
        let named = buckets.compactMap { key, bucket -> (name: String, bytes: UInt64)? in
            guard case .named(let name) = key, bucket.totalBytes > 0 else { return nil }
            return (name, bucket.totalBytes)
        }
        guard !named.isEmpty else { return nil }

        let largestBytes = named.map(\.bytes).max()!
        let leaders = named.filter { $0.bytes == largestBytes }
        // Lexicographic name gives a stable winner without relying on the
        // filesystem's enumeration order; ties remain visible via `tied`.
        let winner = leaders.map(\.name).min()!
        return LargestContributor(name: winner, totalBytes: largestBytes, tied: leaders.count > 1)
    }

    private func kind(for url: URL, isDirectory: Bool) -> ArtifactKind {
        switch url.pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "pkg": .package
        case "dmg": .diskImage
        default: isDirectory ? .directory : .file
        }
    }
}

